    description: "TRIPLEX 3 SUÍTES + ÁTICO COM LAREIRA | CONDOMÍNIO FECHADO | GUABIROTUBA Seu novo lar pode estar aqui! Excelente sobrado triplex com 123 m² privativos, em condomínio fechado no Guabirotuba, oferecendo ambientes amplos, modernos e muito bem distribuídos em 3 pavimentos. Um imóvel pensado para quem valoriza conforto, segurança e praticidade, com o diferencial de contar com 3 suítes e um aconchegante ático com lareira. ? DESTAQUES DO IMÓVEL ? 123 m² de área privativa ? 3 suítes ? Ático com living íntimo e lareira ? Condomínio fechado ? Cozinha americana com armários planejados ? Living para 2 ambientes ? Churrasqueira privativa e coberta ? Área externa nos fundos ? Lavanderia ? 1 vaga de garagem coberta ? Aquecimento a gás ? Interfone ? Sancas e detalhes em gesso ? Porcelanato nas áreas frias ? Laminado nas áreas íntimas AMBIENTES Térreo: Amplo living para 2 ambientes, com porcelanato e teto rebaixado em gesso, lavabo e cozinha estilo americana com armários planejados, integrada ao living. Nos fundos, área externa com lavanderia e churrasqueira com pia de apoio — perfeita para receber familiares e amigos. 2º pavimento: Duas suítes, sendo uma delas com armários. Os banheiros possuem box em vidro, tampos em granito e armários. Escada com elegantes pisadas em granito. 3º pavimento: Um agradável ático com living íntimo, lareira e uma suíte, criando um espaço reservado e aconchegante para momentos de descanso, home office ou convivência. LOCALIZAÇÃO Localizado no Guabirotuba, bairro tradicional de Curitiba, o imóvel combina a tranquilidade de um condomínio fechado com a praticidade de estar próximo a uma ampla estrutura de comércio e serviços. PRONTO PARA LOCAR Se você procura um imóvel com 3 suítes, churrasqueira, ático com lareira e condomínio fechado, vale a pena conhecer este triplex pessoalmente. Entre em contato agora e agende sua visita. As visitas podem ser programadas de acordo com a disponibilidade. Seu próximo endereço pode ser este. Agende sua visita! Valor do aluguel R$3.190,00 com abonode R$290,00 para pagamento no vencimento à partir do segundo mês (aluguel bruto R$ 2.900,00 + IPTU (R$192,70)+ condominio de R$180,00+F.C.I (145,00). Total aproximado mensal a partir do 2º mês, considerando o pagamento pontual: R$ 3.417,70 Garantia Locatícia - Seguro Fiança - ligar para Silvia para fazer a simulação VALORES SUJEITO À ALTERAÇÕES SEM PRÉVIO AVISO!!!. aceita um PET",
