    features: [],
    description: "Apartamento com 2 Quartos e Amplo Terraço no Cabral em Curitiba/PR Excelente oportunidade para quem busca conforto, praticidade e uma localização privilegiada em um dos bairros mais tradicionais e valorizados de Curitiba. Este apartamento oferece ambientes funcionais, dormitórios com armários e um amplo terraço, ideal para quem aprecia espaço extra e momentos de lazer ao ar livre. Localizado na Avenida Munhoz da Rocha, uma das principais e mais charmosas vias do Cabral, o imóvel está em uma região que reúne praticidade e conveniência. Nas proximidades, você encontrará o Quadrata Cabral Mall, além de ampla variedade de comércios, restaurantes, supermercados, agências bancárias, serviços e opções de transporte, facilitando a rotina e o acesso a diferentes regiões da cidade. O Edifício Ana Maria é um condomínio residencial tradicional, situado em uma região consolidada do Cabral. O apartamento está localizado no 3º andar, sem elevador, sendo uma excelente opção para quem valoriza localização, funcionalidade e espaço. O imóvel está dividido em: Sala; Cozinha; 02 dormitórios com armários; Banheiro social com box; Área de serviço; Vaga de garagem exclusiva; Amplo terraço. Valores: Valor do Aluguel Bruto: R$ 2.640,00 Bonificação para pagamento em dia (até o dia 05): R$ 440,00 Valor do Aluguel Líquido: R$ 2.200,00 Condomínio aproximadamente: R$ 600,00 IPTU: R$ 78,49 FCI: R$ 110,00 Seguro-incêndio: R$ 42,00 / mensal (Incluso assistência residencial Porto Seguros). Todos os valores estão sujeitos à alteração sem prévio aviso.",
